def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for site in s.get('sites') or []:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        o = site.get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if r is not None and isfinite(r) and r > 0:
            total += o * r * r * r
            weight += o
    return 4.0 * pi * total / (3.0 * weight * v) if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for i in range(n):
        o = sites[i].get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if isfinite(nearest[i]):
            total += o * nearest[i]
            weight += o
    return total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    nearest = [inf] * n
    occ = []
    for site in sites:
        o = site.get('occupancy')
        occ.append(1.0 if o is None else max(0.0, o))
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and 0 < d <= 1.25 * nearest[i]:
            counts[i] += occ[j]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if isfinite(nearest[i]):
            total += occ[i] * counts[i]
            weight += occ[i]
    return total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    nearest = [inf] * n
    occ = []
    for site in sites:
        o = site.get('occupancy')
        occ.append(1.0 if o is None else max(0.0, o))
    for edge in edges:
        i = edge.get('i', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and 0 < d <= 1.25 * nearest[i]:
            counts[i] += occ[j]
    weight = 0.0
    total = 0.0
    square = 0.0
    for i in range(n):
        if isfinite(nearest[i]):
            weight += occ[i]
            total += occ[i] * counts[i]
            square += occ[i] * counts[i] * counts[i]
    if weight <= 0:
        return 0.0
    return sqrt(max(0.0, square / weight - (total / weight) ** 2))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = []
    for site in sites:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        radii.append(r if r is not None and isfinite(r) and r > 0 else 0.0)
    n = len(sites)
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and radii[i] > 0 and radii[j] > 0 and d is not None and isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    values = sorted([x for x in nearest if isfinite(x)])
    if not values:
        return 0.0
    position = 0.1 * (len(values) - 1)
    lo = int(position)
    hi = min(lo + 1, len(values) - 1)
    return values[lo] + (position - lo) * (values[hi] - values[lo])

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        x = (props.get(element) or {}).get('first_ionization_energy_eV')
        if fraction is not None and isfinite(fraction) and fraction > 0 and x is not None and isfinite(x):
            total += fraction * x
            weight += fraction
    return total / weight if weight > 0 else 0.0

