def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        lengths = [lattice.get('a_A'), lattice.get('b_A'), lattice.get('c_A')]
    values = [x for x in lengths if x is not None and isfinite(x) and x > 0]
    if len(values) != 3:
        return 0.0
    return log(max(values) / min(values))
